        val newestOnly = """[{"id":999,"draft":false,"assets":[]}]"""
        val server = MockWebServer()
        server.dispatcher = object : Dispatcher() {
            override fun dispatch(request: RecordedRequest): MockResponse {
                return if (request.requestUrl?.queryParameter("per_page") == "1") {
                    MockResponse().setResponseCode(200).setBody(newestOnly)
                } else {
                    MockResponse().setResponseCode(200).setBody(largeHistoricalFeed)
                }
            }
        }
        server.start()
        try {
            val client = GitHubReleaseAssetClient(
                tokenProvider = { "test-token" },
                releasesUrl = server.url("/repos/riyas433554-dot/vyom-android/releases?per_page=1").toString()
            )
            assertEquals(newestOnly, client.readReleases(512 * 1024))
            val request = server.takeRequest()
            assertEquals("1", request.requestUrl?.queryParameter("per_page"))
            assertEquals("Bearer test-token", request.getHeader("Authorization"))
        } finally {
            server.shutdown()
        }
